// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint timestamp1, uint timestamp2) public {
        vm.assume(sender != address(0));
        vm.assume(timestamp1 >= 1);
        vm.assume(timestamp2 == timestamp1);

        vm.deal(sender, 30 ether);

        vm.warp(timestamp1);
        vm.prank(sender);
        (bool ok1, ) = address(c).call{value: 10 ether}("");

        vm.warp(timestamp2);
        vm.prank(sender);
        (bool ok2, ) = address(c).call{value: 10 ether}("");

        // In reference, second call reverts because timestamp not strictly greater
        // In mutant, second call succeeds because timestamp >= pastBlockTime
        assertTrue(ok1 && !ok2, "Reference property: second call in same timestamp must revert");
    }
}

